        "count",
        "loss_m"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "loss_ratio",
      "description": "نسبت زیان به درآمد",
      "formula": "زیان دوره تقسیم بر درآمد همان دوره",
      "unit": "درصد",
      "dimensions": [
